import React, { useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';
import Header from '../../components/client/Header';
import Footer from '../../components/client/Footer';
import '../../styles/home.css';

function MyOrders() {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [expandedOrder, setExpandedOrder] = useState(null);
    const history = useHistory();
    const userId = localStorage.getItem('userId');

    useEffect(() => {
        if (!userId) {
            history.push('/login');
            return;
        }

        fetch(`http://localhost:3001/order/user/${userId}`)
            .then(res => res.json())
            .then(data => {
                setOrders(data);
                setLoading(false);
            })
            .catch(err => {
                console.error("Erreur lors de la récupération des commandes:", err);
                setLoading(false);
            });
    }, [userId, history]);

    const toggleOrder = (idOrder) => {
        if (expandedOrder === idOrder) {
            setExpandedOrder(null);
        } else {
            setExpandedOrder(idOrder);
        }
    };

    const statusSteps = ['payee', 'preparation', 'expediee', 'livree'];
    const statusLabels = {
        'en_attente': 'En attente',
        'payee': 'En cours (Payée)',
        'preparation': 'En préparation',
        'expediee': 'En livraison',
        'livree': 'Livrée',
        'annulee': 'Annulée'
    };

    if (loading) return <div style={{ textAlign: 'center', marginTop: '50px' }}>Chargement de vos commandes...</div>;

    return (
        <div className="home">
            <Header />
            <div className="container" style={{ display: 'block', maxWidth: '800px', margin: '40px auto', minHeight: '60vh' }}>
                <h1 style={{ marginBottom: '20px' }}>Mes Commandes</h1>

                {orders.length === 0 ? (
                    <p>Vous n'avez passé aucune commande pour le moment.</p>
                ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        {orders.map(order => {
                            const orderTotal = order.items.reduce((acc, item) => acc + (item.unitPrice * item.quantity), 0);
                            const isExpanded = expandedOrder === order.idOrder;

                            // Calculate progress for breadcrumb
                            let currentStepIndex = statusSteps.indexOf(order.currentStatus);
                            if (currentStepIndex === -1 && order.currentStatus === 'en_attente') currentStepIndex = 0; // fallback

                            return (
                                <div key={order.idOrder} style={{ border: '1px solid #ddd', borderRadius: '8px', overflow: 'hidden' }}>
                                    {/* En-tête de la commande (cliquable) */}
                                    <div 
                                        onClick={() => toggleOrder(order.idOrder)}
                                        style={{ backgroundColor: '#f5f5f5', padding: '15px', cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}
                                    >
                                        <div>
                                            <h3 style={{ margin: 0 }}>Commande n°{order.idOrder}</h3>
                                            <span style={{ fontSize: '14px', color: '#666' }}>
                                                Passée le {new Date(order.date).toLocaleDateString('fr-FR')}
                                            </span>
                                        </div>
                                        <div style={{ textAlign: 'right' }}>
                                            <p style={{ margin: 0, fontWeight: 'bold' }}>{orderTotal.toFixed(2)} €</p>
                                            <span style={{ fontSize: '14px', color: '#1890ff' }}>
                                                {isExpanded ? '▲ Voir moins' : '▼ Voir plus'}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Détails de la commande (dépliant) */}
                                    {isExpanded && (
                                        <div style={{ padding: '20px', backgroundColor: '#fff' }}>
                                            
                                            {/* Fil d'ariane / Barre de progression */}
                                            {order.currentStatus !== 'annulee' ? (
                                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '30px', position: 'relative' }}>
                                                    {/* Ligne de fond */}
                                                    <div style={{ position: 'absolute', top: '15px', left: '10%', right: '10%', height: '4px', backgroundColor: '#eee', zIndex: 1 }}></div>
                                                    
                                                    {statusSteps.map((step, index) => {
                                                        const isCompleted = index <= currentStepIndex;
                                                        return (
                                                            <div key={step} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', zIndex: 2, width: '25%' }}>
                                                                <div style={{ 
                                                                    width: '30px', height: '30px', borderRadius: '50%', 
                                                                    backgroundColor: isCompleted ? '#28a745' : '#ccc',
                                                                    color: 'white', display: 'flex', justifyContent: 'center', alignItems: 'center',
                                                                    fontWeight: 'bold', marginBottom: '8px'
                                                                }}>
                                                                    {isCompleted ? '✓' : index + 1}
                                                                </div>
                                                                <span style={{ fontSize: '12px', textAlign: 'center', color: isCompleted ? '#333' : '#999' }}>
                                                                    {statusLabels[step]}
                                                                </span>
                                                            </div>
                                                        );
                                                    })}
                                                </div>
                                            ) : (
                                                <div style={{ color: 'red', fontWeight: 'bold', marginBottom: '20px', textAlign: 'center' }}>
                                                    Cette commande a été annulée.
                                                </div>
                                            )}

                                            {/* Liste des articles */}
                                            <h4 style={{ borderBottom: '1px solid #eee', paddingBottom: '10px', marginBottom: '15px' }}>Articles commandés</h4>
                                            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                                                {order.items.map(item => (
                                                    <div key={item.idItem} style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                                                        <img src={item.image} alt={item.name} style={{ width: '60px', height: '60px', objectFit: 'cover', borderRadius: '4px', border: '1px solid #eee' }} />
                                                        <div style={{ flex: 1 }}>
                                                            <h5 style={{ margin: '0 0 5px 0' }}>{item.name}</h5>
                                                            <p style={{ margin: 0, fontSize: '14px', color: '#555' }}>Quantité : {item.quantity}</p>
                                                        </div>
                                                        <div style={{ fontWeight: 'bold' }}>
                                                            {(item.unitPrice * item.quantity).toFixed(2)} €
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
            <Footer />
        </div>
    );
}

export default MyOrders;
